INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Nelua · Safer systems contracts', 'Catch mistakes at the boundary where resources and pointers change hands.', 0, 'nelua') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Nelua · Data, errors and representation', 'Express intent without hiding storage or conversion costs.', 1, 'nelua') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Nelua · Platforms and hardware', 'Make configurations and hardware boundaries explicit.', 2, 'nelua') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO categories (name, tagline, sort_order, mod) VALUES ('Nelua · Language experiments and tools', 'Explore ideas with explicit lowering and storage.', 3, 'nelua') ON CONFLICT (name) DO UPDATE SET tagline = excluded.tagline, sort_order = excluded.sort_order, mod = excluded.mod;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-borrow', 'nelua', 'Nelua · Safer systems contracts', 'Scoped borrowing and escape checks', 'Catch references that outlive their storage.', 'Reject a returned stack reference or a reference-capturing closure stored past its frame. Start with bounded checks rather than full lifetime inference.', 'Extend analysis of local references, borrowed spans and by-reference captures; validate with compiler examples and Nelibc buffers.', 'Aliases through raw pointers, imported C and calls need explicit boundaries; bounded checking is not a memory safety proof.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 1, 0, 'low', 'large', 0, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-capabilities', 'nelua', 'Nelua · Safer systems contracts', 'Function capability contracts', 'State which functions may allocate, block or call platform services.', 'An allocator helper or signal handler reports the exact call that introduces a forbidden dependency.', 'Check explicit contracts transitively across known callees; require declared contracts at foreign and indirect-call boundaries.', 'Separate allocation, blocking and platform effects precisely; unknown callbacks must not silently count as safe.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 0, 0, 'medium', 'large', 1, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-typestate', 'nelua', 'Nelua · Safer systems contracts', 'Resource typestate', 'Make legal resource transitions visible in types.', 'An open handle can be read; a closed handle cannot. Starting a device queue consumes its configured state.', 'Prototype owned wrappers with distinct state types before deciding whether compiler support is needed.', 'Error recovery and partially completed transitions must preserve ownership without excessive wrapper code.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 0, 0, 'high', 'medium', 2, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-storage', 'nelua', 'Nelua · Safer systems contracts', 'Caller-supplied storage', 'Use bounded output and scratch buffers consistently.', 'A formatter or parser accepts your storage and reports required capacity or useful partial progress.', 'Design library conventions for spans, scratch regions, allocator choice and failure semantics; try Nelibc formatting wrappers.', 'Partial writes and required-size reporting need precise contracts. Existing spans do not establish storage lifetime.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 0, 0, 'high', 'medium', 3, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-named-variants', 'nelua', 'Nelua · Data, errors and representation', 'Named variant cases', 'Distinguish alternatives even when their payload types match.', 'Read(fd) and Write(fd) are separate cases with the same descriptor representation.', 'Extend variant construction and exhaustive match to named cases; prove it on protocol messages and parser nodes.', 'Define namespacing, zero initialization and compatibility with existing type-based variants.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 1, 0, 'medium', 'large', 4, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-distinct', 'nelua', 'Nelua · Data, errors and representation', 'Distinct types and controlled conversions', 'Keep descriptors, byte counts, pages and addresses apart.', 'Adding a byte count to an address is permitted; adding two file descriptors is rejected.', 'Prototype distinct wrappers and selected operators, then assess a representation-preserving type declaration.', 'Define explicit conversion, ABI, generic matching and which operations preserve the distinct type.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 1, 0, 'medium', 'medium', 5, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-arithmetic', 'nelua', 'Nelua · Data, errors and representation', 'Explicit checked arithmetic', 'Choose checked, wrapping or saturating operations deliberately.', 'Compute allocation count times element size and handle overflow before reserving memory.', 'Provide consistent integer operations and checked narrowing; align compile-time evaluation with generated C.', 'Signed overflow, target widths and conversion edges must have defined semantics in both evaluators.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 1, 0, 'high', 'medium', 6, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-errors', 'nelua', 'Nelua · Data, errors and representation', 'Typed errors and propagation', 'Preserve failure information with Result(T, E).', 'A parser distinguishes invalid input, truncated input and insufficient output capacity, with exhaustive handling.', 'Start with a variant-backed library and explore propagation that composes with existing optional question-mark syntax.', 'Success and error payloads may have the same type; propagation and owned payload cleanup need clear rules.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 0, 0, 'medium', 'medium', 7, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-binary-layout', 'nelua', 'Nelua · Data, errors and representation', 'Binary layout descriptions', 'Describe byte order, field widths and validation together.', 'Parse ELF or TZif data and packets without treating wire bytes as native structs.', 'Generate bounded readers and writers from a compile-time schema; verify offsets independently of native C layout.', 'Unaligned access, malformed lengths, overflow and versioned formats require explicit behavior.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 0, 0, 'high', 'medium', 8, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-platform-config', 'nelua', 'Nelua · Platforms and hardware', 'Validated compile-time platform descriptions', 'Build and validate static platform configuration in one place.', 'A platform without a clock explicitly rejects timed waits or selects an unsupported-operation implementation.', 'Extend typed compile-time configuration into callback validation, operation tables and generated bindings; try Nelibc host operations.', 'Distinguish an absent capability from a runtime failure. Keep the core independent of workshop consumers.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 0, 0, 'high', 'medium', 9, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-mmio', 'nelua', 'Nelua · Platforms and hardware', 'Typed hardware memory access', 'Give device registers access rules beyond ordinary memory.', 'A write-only register cannot be read, and a write-one-to-clear register gets an appropriate operation.', 'Prototype register accessors with widths and permissions; add compiler support only where emission guarantees require it.', 'Volatile access is not an atomic or ordering guarantee. Architecture-specific barriers and exact access widths need validation.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 0, 0, 'medium', 'large', 10, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-relative-refs', 'nelua', 'Nelua · Platforms and hardware', 'Relative references into regions', 'Store checked offsets instead of process-specific pointers.', 'Move or map a data structure at a new base and resolve its references against an explicit region.', 'Prototype region-bound offsets and checked resolution for shared memory or mapped data.', 'Region identity, alignment, overflow, mutation and temporary pointer lifetime all need contracts.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 0, 0, 'medium', 'large', 11, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-state-machines', 'nelua', 'Nelua · Language experiments and tools', 'Typed protocol and state-machine descriptions', 'Describe states, messages and legal transitions together.', 'A protocol handler handles every legal input and makes forbidden transitions explicit.', 'Use syntax extensions and compile-time generation of ordinary records and dispatch; start with a small incremental protocol.', 'Define failure transitions, ownership and async boundaries; avoid claiming that a generated machine verifies the whole protocol.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 0, 0, 'medium', 'large', 12, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-generators', 'nelua', 'Nelua · Language experiments and tools', 'Generators with visible storage', 'Suspend and resume a function through a caller-owned state record.', 'An incremental parser resumes as bytes arrive without a separate stack or implicit heap allocation.', 'Lower suspension points into explicit state and lifecycle operations with a documented layout policy.', 'Ownership, references across suspension, cleanup and cancellation are major design questions.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 0, 0, 'low', 'large', 13, 1, 0)
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('nelua-typed-holes', 'nelua', 'Nelua · Language experiments and tools', 'Typed holes for development', 'Ask the compiler what belongs in an unfinished expression.', 'A placeholder reports the expected type, available bindings and unmet generic constraints.', 'Add a diagnostic-only placeholder that cannot enter an executable; try it in generic and compile-time examples.', 'Keep suggestions bounded and accurate in the presence of forward inference and unresolved types.', 'Nelua systems, Nelibc, firmware and driver developers', 0, 1, 0, 0, 'high', 'medium', 14, 1, 0)
